 const input = $input.first().json;

const msg = input.message_text.toLowerCase();

// Deduplication — ignore if same message processed within 3 seconds

const staticData = $getWorkflowStaticData('global');

if (!staticData.lastMessages) staticData.lastMessages = {};

const msgKey = `${input.sender_jid}_${input.message_text}`;

const now = Date.now();

if (staticData.lastMessages[msgKey] && (now - staticData.lastMessages[msgKey]) < 3000) {

  return [];

}

staticData.lastMessages[msgKey] = now;

// Clean old entries

Object.keys(staticData.lastMessages).forEach(k => {

  if (now - staticData.lastMessages[k] > 10000) delete staticData.lastMessages[k];

});

const reservationKeywords = ['reserv', 'book', 'tisch', 'buchen', 'table', 'reservation', 'reservierung', 'platz', 'seat'];

const viewKeywords = ['show reservation', 'my booking', 'meine reservierung', 'check booking', 'today', 'heute', 'all reservation', 'alle reservierung'];

const cancelKeywords = ['cancel', 'stornieren', 'delete reservation', 'remove booking', 'absagen'];

let intent = 'general';

if (cancelKeywords.some(k => msg.includes(k))) intent = 'cancel_reservation';

else if (viewKeywords.some(k => msg.includes(k))) intent = 'view_reservations';

else if (reservationKeywords.some(k => msg.includes(k))) intent = 'make_reservation';

