const data = $input.first().json;
const msg = data.message_text;

const staticData = $getWorkflowStaticData('global');
if (!staticData.chatHistory) staticData.chatHistory = {};
const history = (staticData.chatHistory[data.sender_jid] || []).slice(-6);

const systemPrompt = `You are Demo, the warm digital assistant for Cafe Demo Berlin.

LANGUAGE RULE: Respond in the SAME language as the user. English → English. German → German.

Your job is to collect reservation details in a friendly, barista-like way. You need:
1. Date (e.g. Saturday June 14 / Samstag 14. Juni)
2. Time (e.g. 19:00)
3. Number of guests (minimum 4 — walk-ins for smaller groups)
4. Name for the reservation

Opening hours: Mon-Fri 07:00-20:00, Sat 08:00-21:00, Sun 09:00-18:00.

If user provides ALL 4 details respond with ONLY this JSON and nothing else:
CONFIRM_RESERVATION:{"date":"2024-06-14","time":"19:00","guests":4,"name":"Mueller","display_date":"Saturday June 14"}

If details are missing, ask warmly for the missing ones. Keep it SHORT and friendly.
Use ☕ and 📅 emojis naturally. Never use ## headers. Never use ** double asterisks.`;

const messagesWithSystem = [
  { role: 'system', content: systemPrompt },
  ...history,
  { role: 'user', content: msg }
];

return [{ json: { ...data, ollama_payload: { 
  model: 'gemma2:2b', 
  messages: messagesWithSystem, 
  stream: false, 
  options: { temperature: 0.3, num_predict: 300 } 
} } }];

const ollamaData = $input.first().json;
const data = {
  ...ollamaData,
  sender_jid: $('Reservation Prompt').first().json.sender_jid,
  message_text: $('Reservation Prompt').first().json.message_text,
  session: $('Reservation Prompt').first().json.session || 'default'
};

const response = data.message?.content || '';

if (response.includes('CONFIRM_RESERVATION:')) {
  const jsonStr = response.split('CONFIRM_RESERVATION:')[1].trim();
  try {
    const reservation = JSON.parse(jsonStr);
    return [{ json: { 
      sender_jid: data.sender_jid,
      message_text: data.message_text,
      session: data.session,
      is_confirmed: true,
      reservation,
      reply_text: null
    }}];
  } catch(e) {
    // Parse failed, treat as normal response
  }
}

const staticData = $getWorkflowStaticData('global');
if (!staticData.chatHistory) staticData.chatHistory = {};
if (!staticData.chatHistory[data.sender_jid]) staticData.chatHistory[data.sender_jid] = [];
staticData.chatHistory[data.sender_jid].push(
  { role: 'user', content: data.message_text },
  { role: 'assistant', content: response }
);
if (staticData.chatHistory[data.sender_jid].length > 6) {
  staticData.chatHistory[data.sender_jid] = staticData.chatHistory[data.sender_jid].slice(-6);
}

let clean = response.replace(/##?\s*/g, '').replace(/\*\*/g, '').trim();
if (clean.length > 600) clean = clean.substring(0, 597) + '...';

return [{ json: { 
  sender_jid: data.sender_jid,
  message_text: data.message_text,
  session: data.session,
  is_confirmed: false,
  reply_text: clean 
}}];

