const data = $input.first().json;

// Get sender_jid from previous nodes if missing
const sender_jid = data.sender_jid || $('Parse Reservation Response').first().json.sender_jid;
const message_text = data.message_text || $('Parse Reservation Response').first().json.message_text;
const r = data.reservation || $('Parse Reservation Response').first().json.reservation;

if (!r) {
  return [{ json: { 
    sender_jid: sender_jid,
    session: 'default',
    reply_text: '✅ Your reservation has been saved!'
  }}];
}

const isGerman = /[äöüßÄÖÜ]|\b(ich|bitte|danke|tisch|reservierung|uhr)\b/i.test(message_text || '');

let reply;
if (isGerman) {
  reply = `✅ *Reservierung bestätigt!*\n\n- *Datum:* ${r.display_date}\n- *Uhrzeit:* ${r.time} Uhr\n- *Personen:* ${r.guests}\n- *Name:* ${r.name}\n\nWir freuen uns auf Ihren Besuch!`;
} else {
  reply = `✅ *Reservation confirmed!*\n\n- *Date:* ${r.display_date}\n- *Time:* ${r.time}\n- *Guests:* ${r.guests}\n- *Name:* ${r.name}\n\nWe look forward to seeing you!`;
}

return [{ json: { 
  sender_jid: sender_jid,
  session: 'default',
  reply_text: reply
}}];

const data = $input.first().json;
const today = new Date().toISOString().split('T')[0];
const files = data.files || [];

const todayFiles = files.filter(f => f.includes(today));

const isGerman = /[äöüßÄÖÜ]|\b(ich|bitte|danke|heute|reservierung)\b/i.test(data.message_text || '');

let reply;
if (todayFiles.length === 0) {
  reply = isGerman 
    ? `📋 Heute (${today}) sind keine Reservierungen vorhanden.`
    : `📋 No reservations found for today (${today}).`;
} else {
  const list = todayFiles.map(f => `- ${f.replace('.md','').replace('Reservations/','')}`).join('\n');
  reply = isGerman
    ? `📋 *Reservierungen heute (${today}):*\n\n${list}`
    : `📋 *Today's reservations (${today}):*\n\n${list}`;
}

return [{ json: { ...data, reply_text: reply } }];

